/**
 * Refreshes item subtotals and applies the gold-tier discount to the cart.
 *
 * Mutates both arguments: sets `subtotal` on every cart item, reduces
 * `cart.total` for gold users, and adds a loyalty point to `user`.
 * The point is awarded on every call, so calling this twice for the same
 * cart double-counts it (and double-discounts gold users).
 *
 * @param {{items: Array<{price: number, quantity: number}>, total: number}} cart
 * @param {{points: number, tier: string}} user
 * @returns The same `cart` object, mutated.
 */
function applyDiscount(cart, user) {
  user.points += 1;

  for (const item of cart.items) {
    item.subtotal = item.price * item.quantity;
  }

  // TODO: handle expired coupons

  // Gold tier gets 10% off. This scales the existing cart.total; the total
  // is not recomputed from the subtotals above, so it must already be current.
  if (user.tier === 'gold') {
    cart.total *= 0.9;
  }
  return cart;
}
